ALTER TABLE asset_version ADD COLUMN manifest_sealed INTEGER NOT NULL DEFAULT 0 CHECK(manifest_sealed IN (0,1));
CREATE TRIGGER immutable_manifest_seal BEFORE UPDATE OF manifest_sealed ON asset_version WHEN OLD.manifest_sealed=1 AND NEW.manifest_sealed!=1 BEGIN SELECT RAISE(ABORT,'immutable_manifest'); END;
CREATE TRIGGER sealed_artifact_manifest BEFORE INSERT ON version_artifact WHEN (SELECT manifest_sealed FROM asset_version WHERE id=NEW.version_id)=1 BEGIN SELECT RAISE(ABORT,'immutable_artifact_manifest'); END;
CREATE TRIGGER verified_member_epoch AFTER UPDATE OF emailVerified ON user WHEN EXISTS(SELECT 1 FROM member WHERE user_id=NEW.id) BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER version_state_machine BEFORE UPDATE OF state ON asset_version WHEN OLD.state!=NEW.state AND NOT ((OLD.state='draft' AND NEW.state IN ('submitted','withdrawn')) OR (OLD.state='submitted' AND NEW.state IN ('processing','withdrawn')) OR (OLD.state='processing' AND NEW.state IN ('awaiting_review','withdrawn')) OR (OLD.state='awaiting_review' AND NEW.state IN ('changes_requested','rejected','approved','withdrawn')) OR (OLD.state='changes_requested' AND NEW.state IN ('submitted','withdrawn')) OR (OLD.state='rejected' AND NEW.state='withdrawn') OR (OLD.state='approved' AND NEW.state IN ('published','withdrawn')) OR (OLD.state='published' AND NEW.state='withdrawn')) BEGIN SELECT RAISE(ABORT,'invalid_version_transition'); END;
